function fieldp(id,l,ph){return '<div><label for="'+id+'">'+l+'</label><input id="'+id+'" maxlength="120" autocomplete="off" placeholder="'+esc(ph)+'"></div>'}
function noteOK(s){
  s=String(s).trim();
  var words=s.toLowerCase().match(/[a-zàèéìòù]+/g)||[];
  if(s.length<10||words.length<2)return false;
  var w3=0,ok=0;
  words.forEach(function(w){
    if(w.length<3)return;
    w3++;
    var v=(w.match(/[aeiouàèéìòù]/g)||[]).length,bad=false;
    if(v===0||v/w.length<0.2)bad=true;
    if(/([a-zàèéìòù])\1\1/.test(w))bad=true;
    if(/[bcdfghjklmnpqrstvwxyz]{5,}/.test(w))bad=true;
    if(w.length>=4&&/^(.{2,3})\1+$/.test(w))bad=true;
    if(/(asdf|sdfg|dfgh|fghj|ghjk|hjkl|qwer|wert|erty|rtyu|tyui|yuio|uiop|zxcv|xcvb|cvbn|vbnm)/.test(w))bad=true;
    if(!bad)ok++;
  });
  return ok>=2&&w3>0&&ok/w3>=0.7;
}
