  l.forEach(function(x){if(x.sq)(g[x.sq]=g[x.sq]||[]).push(x);else solo.push(x)});
  var ids=Object.keys(g).filter(function(k){if(g[k].length<2){solo=solo.concat(g[k]);return false}return true});
  var me=S.agent?S.agent.m:"";
