var HGSVG='<svg class="hg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 2h12M6 22h12M7 2v4.5a5 5 0 0 0 1.5 3.5L12 12l3.5-2a5 5 0 0 0 1.5-3.5V2M7 22v-4.5a5 5 0 0 1 1.5-3.5L12 12l3.5 2a5 5 0 0 1 1.5 3.5V22"/></svg>';
function sendReq(toM){
  var me=S.agent,to=D.onl.filter(function(x){return x.m===toM})[0];
  if(!to||to.sq)return false;
  if(D.req.some(function(r){return r.da.m===me.m&&r.a.m===toM&&r.st==="attesa"}))return false;
  D.req=D.req.concat([{id:me.m+"-"+toM+"-"+Date.now(),da:{m:me.m,n:me.n,g:me.g},a:{m:to.m,n:to.n,g:to.g},ts:Date.now(),st:"attesa"}]);
  return true;
}
function answerReq(id,ok){
  var rs=D.req,r=rs.filter(function(x){return x.id===id})[0];
  if(!r||r.st!=="attesa")return;
  r.st=ok?"accettata":"rifiutata";
  if(ok){
    var on=D.onl,a=on.filter(function(x){return x.m===r.da.m})[0],b=on.filter(function(x){return x.m===r.a.m})[0];
    if(a&&b){var sid=a.sq||b.sq||("SQ-"+r.da.m+"-"+Date.now());a.sq=sid;b.sq=sid;D.onl=on}
    else{r.st="scaduta";toast("Il collega non è più in servizio")}
  }
  D.req=rs;
  if(S.svc){S.svc.c=compText();svcSave()}
  reqTick();
  if(S.agent&&(S.tab==="srv"||S.tab==="onl"))render();
}
var NOTI={};
function reqTick(){
  var box=$("rq");if(!box)return;
  if(!S.agent){box.classList.add("hide");box.dataset.id="";S.t0=0;return}
  var now=Date.now(),me=S.agent.m,rs=D.req,ch=false;
  if(!S.t0)S.t0=now;
  rs.forEach(function(r){if(r.st==="attesa"&&now-r.ts>=20000){r.st="scaduta";ch=true}});
  var keep=rs.filter(function(r){return now-r.ts<600000});
  if(keep.length!==rs.length){rs=keep;ch=true}
  if(ch)D.req=rs;
  rs.forEach(function(r){
    if(r.da.m===me&&r.st!=="attesa"&&r.ts>=S.t0-1000&&!NOTI[r.id]){
      NOTI[r.id]=1;
      toast(r.st==="accettata"?r.a.n+" ha accettato: siete in squadra":(r.st==="rifiutata"?r.a.n+" non ha accettato":r.a.n+" non ha risposto"));
      if(S.svc){S.svc.c=compText();svcSave()}
      if(S.tab==="srv"||S.tab==="onl")render();
    }
  });
  var p=rs.filter(function(r){return r.a.m===me&&r.st==="attesa"})[0];
  if(!p){box.classList.add("hide");box.dataset.id="";return}
  var left=Math.max(0,20-Math.floor((now-p.ts)/1000));
  if(box.dataset.id!==p.id){
    box.dataset.id=p.id;
    box.innerHTML='<span class="cnt">'+HGSVG+'<b id="rqs">'+left+'</b>s</span><h3>Richiesta di squadra</h3><p><b>'+esc(p.da.n)+'</b> ('+esc(p.da.m)+') · '+esc(p.da.g)+'</p><p>vuole fare servizio con te.</p><div class="rqb"><button class="btn" id="rqy" type="button">Accetto</button><button class="btn sec" id="rqn" type="button">Non accetto</button></div>';
    $("rqy").onclick=function(){answerReq(p.id,true)};$("rqn").onclick=function(){answerReq(p.id,false)};
  }else{var s=$("rqs");if(s)s.textContent=left}
  box.classList.remove("hide");
}
setInterval(reqTick,500);
setInterval(function(){var r=$("rost");if(r&&S.agent)r.innerHTML=rostHtml();if(S.agent&&S.tab==="onl"&&S.svc!==undefined)render()},3000);
function servizio(){
  if(!S.svc){S.skip=false;render();return}
  var v=S.svc,h="";
  h+='<div class="detail" style="margin:0 0 18px"><h3>Servizio in corso</h3><div id="bigtm" style="font:700 44px/1.1 \'Barlow Semi Condensed\',sans-serif;margin:6px 0 10px">'+fmt(Date.now()-v.start)+'</div><dl><dt>Inizio</dt><dd>'+esc(dhm(v.start))+'</dd><dt>Unità</dt><dd>'+esc(v.u)+'</dd><dt>Zona</dt><dd>'+esc(v.z)+'</dd><dt>Veicolo</dt><dd>'+esc(v.v||"-")+'</dd><dt>Compagni</dt><dd>'+esc(compText())+'</dd><dt>Note iniziali</dt><dd>'+esc(v.ni||"-")+'</dd></dl></div>';
  if(S.ending)h+='<div class="formbox"><label for="sf" style="margin-top:0">Note finali</label><textarea id="sf" rows="3" maxlength="500"></textarea><button class="btn" id="sc" type="button">Conferma fine servizio</button> <button class="btn sec" id="sx" type="button" style="margin-top:20px">Annulla</button></div>';
  else h+='<div class="formbox"><label for="sn" style="margin-top:0">Nuova nota di servizio</label><textarea id="sn" rows="2" maxlength="500"></textarea><button class="btn" id="sa" type="button">Aggiungi nota</button> <button class="btn sec" id="se" type="button" style="margin-top:20px">Termina servizio</button></div>';
  h+=v.notes.map(function(x){return '<article class="post"><p>'+esc(x.x)+'</p><div class="pf"><span>'+esc(dhm(x.t))+'</span></div></article>'}).join("");
  h+=inviteHtml()+'<div id="rost">'+rostHtml()+'</div>';
  $("main").innerHTML=h;
  var ib=$("ivb");if(ib)ib.onclick=function(){if(sendReq($("ivs").value)){toast("Richiesta inviata: il collega ha 20 secondi per rispondere");render()}else toast("Richiesta non inviata")};
  var sa=$("sa");if(sa)sa.onclick=function(){var t=$("sn").value.trim();if(!t){toast("Scrivi la nota");return}if(!noteOK(t)){toast(NOTE_ERR);return}S.svc.notes.unshift({t:Date.now(),x:t});svcSave();toast("Nota aggiunta");render()};
  var se=$("se");if(se)se.onclick=function(){S.ending=true;render()};
  var sx=$("sx");if(sx)sx.onclick=function(){S.ending=false;render()};
  var sc=$("sc");if(sc)sc.onclick=function(){
    var fine=Date.now(),nf=$("sf").value.trim();
    if(nf&&!noteOK(nf)){toast(NOTE_ERR);return}
    D.srv.unshift({id:uid("S"),m:S.agent.m,n:S.agent.n,u:v.u,z:v.z,v:v.v,c:compText(),ni:v.ni,notes:v.notes.slice().reverse(),nf:nf,a:v.start,b:fine});
    svcClear();clearInterval(TM);S.svc=null;S.ending=false;D.onl=D.onl.filter(function(x){return x.m!==S.agent.m});toast("Servizio concluso: "+fmt(fine-v.start));render();
  };
}
