var INS={"Agente": "data:image/png;base64,", "Agente scelto": "data:image/png;base64,", "Assistente": "data:image/png;base64,", "Assistente capo": "data:image/png;base64,", "Assistente capo coordinatore": "data:image/png;base64,", "Vice sovrintendente": "data:image/png;base64,", "Sovrintendente": "data:image/png;base64,", "Sovrintendente capo": "data:image/png;base64,", "Sovrintendente capo coordinatore": "data:image/png;base64,", "Vice ispettore": "data:image/png;base64,", "Ispettore": "data:image/png;base64,", "Ispettore capo": "data:image/png;base64,", "Ispettore superiore": "data:image/png;base64,", "Sostituto commissario": "data:image/png;base64,", "Sostituto commissario coordinatore": "data:image/png;base64,", "Vice commissario": "data:image/png;base64,", "Commissario": "data:image/png;base64,", "Commissario capo": "data:image/png;base64,", "Vice questore aggiunto": "data:image/png;base64,", "Vice questore": "data:image/png;base64,", "Primo dirigente": "data:image/png;base64,", "Dirigente superiore": "data:image/png;base64,", "Dirigente generale": "data:image/png;base64,"};
function badge(g){return INS[g]?'<img src="'+INS[g]+'" alt="" style="height:22px;width:auto;vertical-align:middle;margin-right:8px">':""}
