  if(st==="Attiva"&&ini<=Date.now())D.onl=D.onl.filter(function(x){return x.m!==a.m});
  S.susl.push("SOSPENSIONE "+id+" | "+a.m+" "+a.n+" | dal "+dmy(ini)+" | "+(fino?"fino al "+dmy(fino):"senza data di fine")+" | "+mot+" | "+st);
