function navCount(k){return D[k].length}
var UPD_SEC=5,UPD_SIG=null,UPD_LEFT=0,UPD_T=null,UPD_SNOOZE=0,UPD_FULL=0;
function updBase(){return new URL("app.js",location.href).href}
function updFull(){
  if(Date.now()-UPD_FULL<300000)return;UPD_FULL=Date.now();
  fetch(updBase()+"?v="+Date.now(),{cache:"no-store"}).then(function(r){return r.ok?r.text():""}).then(function(tx){
    var m=tx.match(/var BUILD="([^"]+)"/);if(m&&m[1]!==BUILD)updShow();
  }).catch(function(){});
}
function updCheck(){
  if(!/^https?:$/.test(location.protocol)||Date.now()<UPD_SNOOZE||UPD_T)return;
  fetch(updBase()+"?v="+Date.now(),{method:"HEAD",cache:"no-store"}).then(function(r){
    var s=r.headers.get("etag")||r.headers.get("last-modified")||r.headers.get("content-length")||"";
    if(!s){updFull();return}
    if(UPD_SIG===null){UPD_SIG=s;return}
    if(s!==UPD_SIG){UPD_SIG=s;updShow()}
  }).catch(function(){});
}
function updGo(){
  try{sessionStorage.setItem("ps_upd",JSON.stringify({m:S.agent?S.agent.m:"",skip:S.skip,tab:S.tab}))}catch(e){}
  location.reload();
}
function updShow(){
  var box=$("upd");if(!box||UPD_T)return;
  UPD_LEFT=20;
  box.innerHTML='<span class="cnt">'+HGSVG+'<b id="updn">20</b>s</span><h3>Nuovo aggiornamento</h3><p>Il sistema si aggiorna con le novità.</p><div class="rqb"><button class="btn" id="updy" type="button">Aggiorna ora</button><button class="btn sec" id="updn2" type="button">Più tardi</button></div>';
  box.classList.remove("hide");
  $("updy").onclick=function(){updGo()};
  $("updn2").onclick=function(){clearInterval(UPD_T);UPD_T=null;box.classList.add("hide");UPD_SNOOZE=Date.now()+60000};
  UPD_T=setInterval(function(){
    UPD_LEFT--;var n=$("updn");if(n)n.textContent=Math.max(UPD_LEFT,0);
    if(UPD_LEFT<=0){
      var a=document.activeElement;
      if(a&&(a.tagName==="INPUT"||a.tagName==="TEXTAREA")&&a.value){UPD_LEFT=20;return}
      updGo();
    }
  },1000);
}
setInterval(updCheck,UPD_SEC*1000);
updCheck();
document.addEventListener("visibilitychange",function(){if(!document.hidden)updCheck()});
function rk(g){return RANKS.indexOf(g)}
