  if(S.out)h+='<div class="formbox"><label for="oo" style="margin-top:0">Riga da inviare per l\'attivazione</label><textarea id="oo" rows="3" readonly>'+esc(S.out)+'</textarea><button class="btn sec" id="oc" type="button" style="margin-top:12px">Copia riga</button></div>';
