  if(t==="man"){hd=["ID","Intestato a","Reato","Data","Stato"];body=rows.map(function(r){return row(r.id,[r.id,r.chi,r.reato,r.data,tag(r.stato)],[0,0,0,0,1])})}
  if(t==="den"){hd=["ID","Data","Cittadino","Reato","Agente","Stato"];body=rows.map(function(r){return row(r.id,[r.id,r.data,r.chi,r.reato,r.ag,tag(r.stato||"Attiva")],[0,0,0,0,0,1])})}
  if(t==="mul"){hd=["ID","Data","Cittadino","Infrazione","Importo","Stato"];body=rows.map(function(r){return row(r.id,[r.id,r.data,r.chi,r.motivo,eur(r.imp),tag(r.stato)],[0,0,0,0,0,1])})}
