var mobileMenu=document.querySelector(".mobile-menu");
if(mobileMenu){
  mobileMenu.onclick=function(){document.body.classList.toggle("menu-open")};
}
Array.prototype.forEach.call(document.querySelectorAll("#nav button"),function(button){
  button.onclick=function(){document.body.classList.remove("menu-open")};
});
if($("nav")){
  $("nav").addEventListener("click",function(event){
    if(event.target.closest("button"))document.body.classList.remove("menu-open");
  });
}
